-- Run the ENTIRE file once in the Geography project's Supabase SQL Editor as postgres.
-- Includes the current routine and the user's confirmed SH -> SR correction.
-- Re-running preserves both existing draft and published versions.
BEGIN;
SET LOCAL lock_timeout = '10s';
CREATE SCHEMA IF NOT EXISTS geo_routine_private;
REVOKE ALL ON SCHEMA geo_routine_private FROM PUBLIC;
GRANT USAGE ON SCHEMA geo_routine_private TO authenticated;
DO $admin$
DECLARE owner_id uuid; total integer;
BEGIN
  SELECT count(*), (array_agg(id))[1] INTO total,owner_id FROM auth.users
  WHERE lower(email)='sagarmia583@gmail.com';
  IF total<>1 THEN RAISE EXCEPTION 'Exactly one Auth account for sagarmia583@gmail.com is required.'; END IF;
  EXECUTE format('CREATE OR REPLACE FUNCTION geo_routine_private.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='''' AS %L',
    format('SELECT coalesce((SELECT auth.uid()) = %L::uuid,false)',owner_id::text));
END $admin$;
REVOKE ALL ON FUNCTION geo_routine_private.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION geo_routine_private.is_admin() TO authenticated;

CREATE OR REPLACE FUNCTION geo_routine_private.valid_document(d jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT coalesce(jsonb_typeof(d)='object'
   AND jsonb_typeof(d->'entries')='array' AND jsonb_typeof(d->'courses')='array'
   AND jsonb_typeof(d->'teachers')='array' AND jsonb_typeof(d->'periods')='array'
   AND jsonb_typeof(d->'days')='array' AND jsonb_typeof(d->'levels')='array'
   AND jsonb_typeof(d->'notes')='array' AND jsonb_typeof(d->'break')='object'
   AND (d->>'effectiveDate') ~ '^\d{4}-\d{2}-\d{2}$'
   AND (d->>'distributionDate') ~ '^\d{4}-\d{2}-\d{2}$', false)
$$;
REVOKE ALL ON FUNCTION geo_routine_private.valid_document(jsonb) FROM PUBLIC;

CREATE TABLE IF NOT EXISTS public.class_routine_drafts (
  id smallint PRIMARY KEY CHECK (id=1),
  document jsonb NOT NULL CHECK (geo_routine_private.valid_document(document)),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision>0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.class_routine_published (
  id smallint PRIMARY KEY CHECK (id=1),
  document jsonb NOT NULL CHECK (geo_routine_private.valid_document(document)),
  revision bigint NOT NULL CHECK (revision>0),
  published_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.class_routine_drafts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.class_routine_published ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.class_routine_drafts FROM PUBLIC,anon,authenticated;
REVOKE ALL ON public.class_routine_published FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA public TO anon,authenticated;
GRANT SELECT ON public.class_routine_drafts TO authenticated;
GRANT SELECT ON public.class_routine_published TO anon,authenticated;
DROP POLICY IF EXISTS routine_admin_read_draft ON public.class_routine_drafts;
CREATE POLICY routine_admin_read_draft ON public.class_routine_drafts FOR SELECT TO authenticated
 USING ((SELECT geo_routine_private.is_admin()));
DROP POLICY IF EXISTS routine_public_read ON public.class_routine_published;
CREATE POLICY routine_public_read ON public.class_routine_published FOR SELECT TO anon,authenticated USING (true);

CREATE OR REPLACE FUNCTION public.save_class_routine_draft(p_document jsonb,p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE saved public.class_routine_drafts;
BEGIN
  IF NOT geo_routine_private.is_admin() THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF;
  IF NOT geo_routine_private.valid_document(p_document) THEN RAISE EXCEPTION 'Invalid routine document' USING ERRCODE='22023'; END IF;
  UPDATE public.class_routine_drafts SET document=p_document,revision=revision+1,updated_at=now()
    WHERE id=1 AND revision=p_expected_revision RETURNING * INTO saved;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft changed. Reload before saving.' USING ERRCODE='40001'; END IF;
  RETURN to_jsonb(saved);
END $$;
CREATE OR REPLACE FUNCTION public.publish_class_routine(p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE draft public.class_routine_drafts; live public.class_routine_published;
BEGIN
  IF NOT geo_routine_private.is_admin() THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF;
  SELECT * INTO draft FROM public.class_routine_drafts WHERE id=1 FOR UPDATE;
  IF NOT FOUND OR p_expected_revision IS NULL OR draft.revision<>p_expected_revision THEN RAISE EXCEPTION 'Draft changed. Reload and preview again.' USING ERRCODE='40001'; END IF;
  INSERT INTO public.class_routine_published(id,document,revision,published_at)
    VALUES(1,draft.document,draft.revision,now())
    ON CONFLICT(id) DO UPDATE SET document=excluded.document,revision=excluded.revision,published_at=excluded.published_at
    RETURNING * INTO live;
  RETURN to_jsonb(live);
END $$;
REVOKE ALL ON FUNCTION public.save_class_routine_draft(jsonb,bigint) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.publish_class_routine(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_class_routine_draft(jsonb,bigint) TO authenticated;
GRANT EXECUTE ON FUNCTION public.publish_class_routine(bigint) TO authenticated;

